/**
 * Drizzle schema = single source for TypeScript types. DDL is generated by drizzle-kit into ./migrations,
 * then hand-written migrations add what Drizzle cannot express (roles, grants, RLS, append-only audit).
 * Every business table is tenant-scoped (`tenant_id`). See Technical Specification section 3.2.
 */
import { sql } from 'drizzle-orm';
import {
  bigint,
  bigserial,
  boolean,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  date,
} from 'drizzle-orm/pg-core';

export const ROLES = [
  'REQUESTER',
  'PROCUREMENT',
  'DELEGATE',
  'EVALUATOR',
  'CHAIR',
  'LEGAL',
  'CONTRACT_MGR',
  'PROBITY',
  'FINANCE',
  'ADMIN',
  'EXEC',
  'SUPPLIER',
] as const;
export type Role = (typeof ROLES)[number];

export const PHASES = [
  'INTAKE',
  'PLAN',
  'TENDER',
  'EVALUATION',
  'CONTRACT_AWARD',
  'CONTRACT_MGMT',
  'CLOSED',
] as const;

const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`gen_random_uuid()`);
const tenantId = () => uuid('tenant_id').notNull();
const created = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updated = () => timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();
const version = () => integer('version').notNull().default(1);

export const tenant = pgTable('tenant', {
  id: id(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  region: text('region').notNull().default('ap-southeast-2'),
  sector: text('sector', { enum: ['PUBLIC', 'PRIVATE'] }).notNull(),
  config: jsonb('config').notNull().default({}),
  createdAt: created(),
});

export const orgUnit = pgTable('org_unit', {
  id: id(),
  tenantId: tenantId(),
  name: text('name').notNull(),
  parentId: uuid('parent_id'),
  createdAt: created(),
});

export const appUser = pgTable(
  'app_user',
  {
    id: id(),
    tenantId: tenantId(),
    email: text('email').notNull(),
    name: text('name').notNull(),
    orgUnitId: uuid('org_unit_id'),
    passwordHash: text('password_hash').notNull(),
    active: boolean('active').notNull().default(true),
    failedAttempts: integer('failed_attempts').notNull().default(0),
    lockedUntil: timestamp('locked_until', { withTimezone: true }),
    supplierId: uuid('supplier_id'),
    createdAt: created(),
    updatedAt: updated(),
  },
  (t) => [uniqueIndex('app_user_email_uq').on(t.tenantId, t.email)],
);

export const roleAssignment = pgTable(
  'role_assignment',
  {
    id: id(),
    tenantId: tenantId(),
    userId: uuid('user_id').notNull(),
    role: text('role', { enum: ROLES }).notNull(),
    division: text('division'),
    /** A time-bound grant ends here; the role then stops applying (SEC-A05). Null means it does not expire. */
    expiresAt: timestamp('expires_at', { withTimezone: true }),
    grantedBy: uuid('granted_by'),
  },
  (t) => [uniqueIndex('role_assignment_uq').on(t.userId, t.role)],
);

export const delegation = pgTable('delegation', {
  id: id(),
  tenantId: tenantId(),
  scope: text('scope', { enum: ['SOURCING_APPROVAL', 'CONTRACT_SIGNING', 'PUBLISH_PERMISSION'] }).notNull(),
  role: text('role', { enum: ROLES }).notNull(),
  userId: uuid('user_id'),
  maxValue: numeric('max_value', { precision: 14, scale: 2 }).notNull(),
  division: text('division'),
  active: boolean('active').notNull().default(true),
  createdAt: created(),
  updatedAt: updated(),
});

export const supplier = pgTable('supplier', {
  id: id(),
  tenantId: tenantId(),
  company: text('company').notNull(),
  abn: text('abn').notNull(),
  sanctionsStatus: text('sanctions_status', { enum: ['PENDING', 'CLEAR', 'MATCH'] })
    .notNull()
    .default('PENDING'),
  insuranceStatus: text('insurance_status', { enum: ['UNKNOWN', 'CURRENT', 'EXPIRING', 'EXPIRED'] })
    .notNull()
    .default('UNKNOWN'),
  lastCheckedAt: timestamp('last_checked_at', { withTimezone: true }),
  categories: jsonb('categories').notNull().default([]),
  createdAt: created(),
});

export const request = pgTable(
  'request',
  {
    id: id(),
    tenantId: tenantId(),
    number: text('number').notNull(),
    title: text('title').notNull(),
    category: text('category'),
    unspsc: text('unspsc'),
    estimatedValue: numeric('estimated_value', { precision: 14, scale: 2 }),
    currency: text('currency').notNull().default('AUD'),
    termMonths: integer('term_months'),
    businessUnit: text('business_unit'),
    requesterId: uuid('requester_id').notNull(),
    phase: text('phase', { enum: PHASES }).notNull().default('INTAKE'),
    status: text('status', { enum: ['DRAFT', 'SUBMITTED', 'IN_PROGRESS', 'BLOCKED', 'COMPLETE'] })
      .notNull()
      .default('DRAFT'),
    intakeMode: text('intake_mode', { enum: ['SELF_SERVICE', 'TEAM_LED'] })
      .notNull()
      .default('TEAM_LED'),
    complexity: text('complexity', { enum: ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'] }),
    budgetCheck: text('budget_check', { enum: ['NOT_RUN', 'CLEARED', 'EXCEEDED', 'UNAVAILABLE'] })
      .notNull()
      .default('NOT_RUN'),
    taxonomyScheme: text('taxonomy_scheme'),
    taxonomyCode: text('taxonomy_code'),
    taxonomyConfirmed: boolean('taxonomy_confirmed').notNull().default(false),
    workflowId: text('workflow_id'),
    subWorkflow: text('sub_workflow'),
    processSteps: jsonb('process_steps').notNull().default([]),
    processVariations: jsonb('process_variations').notNull().default([]),
    engagements: jsonb('engagements').notNull().default([]),
    nominatedDelegates: jsonb('nominated_delegates').notNull().default({}),
    ecv: jsonb('ecv'),
    sourceSystem: text('source_system'),
    createdAt: created(),
    updatedAt: updated(),
    version: version(),
  },
  (t) => [
    uniqueIndex('request_number_uq').on(t.tenantId, t.number),
    index('request_requester_idx').on(t.requesterId),
  ],
);

