export const auditEvent = pgTable(
  'audit_event',
  {
    seq: bigserial('seq', { mode: 'number' }).primaryKey(),
    tenantId: tenantId(),
    at: timestamp('at', { withTimezone: true }).notNull().defaultNow(),
    actorId: uuid('actor_id'),
    actorRole: text('actor_role'),
    action: text('action').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id'),
    before: jsonb('before'),
    after: jsonb('after'),
    correlationId: text('correlation_id'),
    result: text('result', { enum: ['SUCCESS', 'DENIED', 'FAILED'] })
      .notNull()
      .default('SUCCESS'),
    prevHash: text('prev_hash').notNull(),
    hash: text('hash').notNull(),
  },
  (t) => [
    index('audit_entity_idx').on(t.entityType, t.entityId),
    index('audit_tenant_seq_idx').on(t.tenantId, t.seq),
  ],
);

/** Server-side sessions: enables idle timeout, absolute timeout and immediate revocation (SEC-A07). */
export const session = pgTable(
  'session',
  {
    id: uuid('id').primaryKey(),
    tenantId: tenantId(),
    userId: uuid('user_id').notNull(),
    pool: text('pool', { enum: ['STAFF', 'SUPPLIER'] }).notNull(), // separate identity pools (SEC-A03)
    createdAt: created(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    ip: text('ip'),
    userAgent: text('user_agent'),
    mfaState: text('mfa_state', { enum: ['NOT_REQUIRED', 'VERIFIED', 'ENROLMENT_REQUIRED'] })
      .notNull()
      .default('NOT_REQUIRED'),
    authMethod: text('auth_method', { enum: ['PASSWORD', 'SSO'] })
      .notNull()
      .default('PASSWORD'),
  },
  (t) => [index('session_user_idx').on(t.userId)],
);

export const migrationBatch = pgTable('migration_batch', {
  id: id(),
  tenantId: tenantId(),
  filename: text('filename').notNull(),
  sourceSystem: text('source_system').notNull(),
  status: text('status', { enum: ['VALIDATED', 'CUTOVER', 'CANCELLED'] })
    .notNull()
    .default('VALIDATED'),
  total: integer('total').notNull().default(0),
  uploadedBy: uuid('uploaded_by').notNull(),
  createdAt: created(),
  cutoverAt: timestamp('cutover_at', { withTimezone: true }),
  cutoverBy: uuid('cutover_by'),
});

export const migrationRecord = pgTable(
  'migration_record',
  {
    id: id(),
    tenantId: tenantId(),
    batchId: uuid('batch_id').notNull(),
    rowNo: integer('row_no').notNull(),
    raw: jsonb('raw').notNull(),
    status: text('status', { enum: ['VALID', 'EXCEPTION', 'SKIPPED', 'LOADED'] })
      .notNull()
      .default('VALID'),
    issues: jsonb('issues').notNull().default([]),
    warnings: jsonb('warnings').notNull().default([]),
    reviewedBy: uuid('reviewed_by'),
    reviewedAt: timestamp('reviewed_at', { withTimezone: true }),
    reviewNote: text('review_note'),
    requestId: uuid('request_id'),
    contractId: uuid('contract_id'),
  },
  (t) => [uniqueIndex('migration_row_uq').on(t.batchId, t.rowNo)],
);

export const userMfa = pgTable('user_mfa', {
  userId: uuid('user_id').primaryKey(),
  tenantId: tenantId(),
  secret: text('secret').notNull(),
  confirmed: boolean('confirmed').notNull().default(false),
  lastStep: bigint('last_step', { mode: 'number' }).notNull().default(0),
  createdAt: created(),
});
